from ..base import BaseInterface


class BaseClToolInterface(BaseInterface):
    def _execute_cl_tool_operation(self, alias, timeout, operation, params, flags, trs_ip, filepath=None, filename=None, symlink=None, **kwargs):
        executor = self.command_store.get(alias)
        return executor.execute_command(operation,
                                        params,
                                        flags,
                                        filename,
                                        filepath,
                                        trs_ip,
                                        symlink=symlink,
                                        check_for_errors=kwargs.get('check_for_errors', True),
                                        timeout=timeout,
                                        alias=alias)

    def _execute_cl_commissioning_operation(self, alias, timeout, operation, params, flags, trs_ip, filepath=None, filename=None):
        executor = self.command_store.get(alias)
        return executor.execute_commissioning(operation,
                                              params,
                                              flags,
                                              filename,
                                              filepath,
                                              trs_ip,
                                              timeout=timeout,
                                              alias=alias)

    def _execute_cl_swupdate_operation(self, alias, timeout, operation, params, flags, trs_ip, filepath=None, filename=None):
        executor = self.command_store.get(alias)
        return executor.execute_swupdate(operation,
                                         params,
                                         flags,
                                         filename,
                                         filepath,
                                         trs_ip,
                                         timeout=timeout,
                                         alias=alias)
